local function lang()
	local l = core.settings:get("language") or ""
	if l == "" and core.get_language then l = core.get_language() or "" end
	l = tostring(l):lower():gsub("[_%-].*$","")
	return l
end
local LANGWORD = {de="Sprache",fr="Langue",es="Idioma",it="Lingua",pt="Idioma",nl="Taal",pl="Język",ru="Язык",tr="Dil",ja="言語",zh="语言"}
function fc_langlabel()
	local w = LANGWORD[lang()]
	if w then return "Language / " .. w end
	return "Language"
end

function fc_T(k)
	local lg = lang()
	local t = L[lg] or L.en
	local x = X[lg]
	return (x and x[k]) or t[k] or X.en[k] or L.en[k] or k
end
